import math
import random

def color_graph(adj: list[list[int]]) -> list[int]:
    if not adj:
        return []
    n = len(adj)
    if n == 0:
        return []
    # Determine if input is adjacency matrix or adjacency list
    is_matrix = False
    if n > 0 and len(adj[0]) == n:
        # Check if all rows have length n and entries are 0 or 1
        valid_matrix = True
        for row in adj:
            if len(row) != n:
                valid_matrix = False
                break
            for val in row:
                if val not in (0, 1):
                    valid_matrix = False
                    break
            if not valid_matrix:
                break
        if valid_matrix:
            is_matrix = True
    # Build adjacency list and degree list
    if is_matrix:
        adj_list = [[] for _ in range(n)]
        for i in range(n):
            for j in range(n):
                if adj[i][j] == 1:
                    adj_list[i].append(j)
        degree = [len(adj_list[i]) for i in range(n)]
    else:
        adj_list = adj
        degree = [len(adj_list[i]) for i in range(n)]
    # Edge case: no edges
    if all(d == 0 for d in degree):
        return [0] * n
    # Best coloring found so far
    best_coloring = None
    best_k = float('inf')
    # Try Welsh-Powell ordering first
    order_wp = sorted(range(n), key=lambda x: (-degree[x], x))
    coloring_wp = [-1] * n
    for v in order_wp:
        used = [False] * (best_k if best_k != float('inf') else n)
        for u in adj_list[v]:
            if coloring_wp[u] != -1:
                c = coloring_wp[u]
                if c < len(used):
                    used[c] = True
        color = 0
        while color < len(used) and used[color]:
            color += 1
        coloring_wp[v] = color
        if color + 1 > best_k:
            break
    k_wp = max(coloring_wp) + 1 if coloring_wp else 0
    if k_wp < best_k:
        best_k = k_wp
        best_coloring = coloring_wp[:]
    # Try DSATUR with multiple random tie-breaks
    for _ in range(20):  # limited iterations for speed
        coloring = [-1] * n
        saturated = [0] * n  # saturation degree
        colored_neighbors = [set() for _ in range(n)]  # set of colors used by neighbors
        uncolored = set(range(n))
        for _ in range(n):
            if not uncolored:
                break
            # Select vertex with max saturation, tie-break by degree in uncolored subgraph, then random
            candidates = []
            max_sat = -1
            for v in uncolored:
                if saturated[v] > max_sat:
                    max_sat = saturated[v]
                    candidates = [v]
                elif saturated[v] == max_sat:
                    candidates.append(v)
            if max_sat == -1:
                # all uncolored have saturation 0, choose max degree in uncolored subgraph
                max_deg = -1
                for v in uncolored:
                    deg = 0
                    for u in adj_list[v]:
                        if u in uncolored:
                            deg += 1
                    if deg > max_deg:
                        max_deg = deg
                        candidates = [v]
                    elif deg == max_deg:
                        candidates.append(v)
                if not candidates:
                    candidates = list(uncolored)
            # Random tie-break
            v = random.choice(candidates)
            # Assign smallest available color
            used_colors = colored_neighbors[v]
            color = 0
            while color in used_colors:
                color += 1
            coloring[v] = color
            uncolored.remove(v)
            # Update neighbors
            for u in adj_list[v]:
                if u in uncolored:
                    if color not in colored_neighbors[u]:
                        colored_neighbors[u].add(color)
                        saturated[u] += 1
        k = max(coloring) + 1 if coloring else 0
        if k < best_k:
            best_k = k
            best_coloring = coloring[:]
            if best_k == 1:  # optimal
                break
    # Try RLF (Recursive Largest First) with multiple random tie-breaks
    for _ in range(20):
        uncolored = set(range(n))
        color = 0
        coloring = [-1] * n
        while uncolored:
            # Build maximal independent set for this color
            # Step 1: pick vertex with max degree in G[uncolored]
            max_deg = -1
            candidates = []
            for v in uncolored:
                deg = 0
                for u in adj_list[v]:
                    if u in uncolored:
                        deg += 1
                if deg > max_deg:
                    max_deg = deg
                    candidates = [v]
                elif deg == max_deg:
                    candidates.append(v)
            if not candidates:
                v = next(iter(uncolored))
            else:
                v = random.choice(candidates)
            S = {v}
            # Partition remaining uncolored into U (not adjacent to S) and W (adjacent to S)
            U = set()
            W = set()
            for u in uncolored:
                if u == v:
                    continue
                adjacent = False
                for w in S:
                    if u in adj_list[w] or w in adj_list[u]:
                        adjacent = True
                        break
                if adjacent:
                    W.add(u)
                else:
                    U.add(u)
            # While U not empty, add vertices to S
            while U:
                # Select u in U with max |N(u) ∩ W|
                best_u = None
                max_w_neighbors = -1
                min_deg_in_U = float('inf')
                for u in U:
                    w_neighbors = 0
                    for nb in adj_list[u]:
                        if nb in W:
                            w_neighbors += 1
                    # Tie-break: min degree in G[U]
                    deg_in_U = 0
                    for nb in adj_list[u]:
                        if nb in U:
                            deg_in_U += 1
                    if w_neighbors > max_w_neighbors or (w_neighbors == max_w_neighbors and deg_in_U < min_deg_in_U):
                        max_w_neighbors = w_neighbors
                        min_deg_in_U = deg_in_U
                        best_u = u
                if best_u is None:
                    break
                S.add(best_u)
                U.remove(best_u)
                # Move neighbors of best_u from U to W
                for nb in adj_list[best_u]:
                    if nb in U:
                        U.remove(nb)
                        W.add(nb)
            # Assign color to all in S
            for vertex in S:
                coloring[vertex] = color
                uncolored.remove(vertex)
            color += 1
        k = color  # number of colors used
        if k < best_k:
            best_k = k
            best_coloring = coloring[:]
            if best_k == 1:
                break
    # If still no coloring (should not happen), fallback to greedy
    if best_coloring is None:
        coloring = [-1] * n
        for v in range(n):
            used = [False] * n
            for u in adj_list[v]:
                if coloring[u] != -1:
                    c = coloring[u]
                    if c < n:
                        used[c] = True
            color = 0
            while color < n and used[color]:
                color += 1
            coloring[v] = color
        best_coloring = coloring
    return best_coloring

