import math
import random

def color_graph(adj: list[list[int]]) -> list[int]:
    if not adj:
        return []
    n = len(adj)

    # Detect adjacency matrix: square and binary entries (0 or 1)
    is_matrix = False
    if n > 0 and len(adj[0]) == n:
        is_matrix = True
        for i in range(n):
            if len(adj[i]) != n:
                is_matrix = False
                break
            for val in adj[i]:
                if val not in (0, 1):
                    is_matrix = False
                    break
            if not is_matrix:
                break

    # Build neighbor sets (undirected, no self-loops)
    if is_matrix:
        neighbors = [set() for _ in range(n)]
        for i in range(n):
            for j in range(n):
                if adj[i][j] == 1 and i != j:
                    neighbors[i].add(j)
                    neighbors[j].add(i)
    else:
        neighbors = [set() for _ in range(n)]
        for i in range(n):
            for j in adj[i]:
                if i != j:
                    neighbors[i].add(j)
                    neighbors[j].add(i)

    # Trivial cases
    if n == 1:
        return [0]
    if all(len(neighbors[i]) == 0 for i in range(n)):
        return [0] * n
    if all(len(neighbors[i]) == n - 1 for i in range(n)):
        return list(range(n))

    # Precompute degrees
    deg = [len(neighbors[i]) for i in range(n)]

    # Helper: greedy coloring with given order
    def greedy_color(order):
        color = [-1] * n
        for v in order:
            used = [False] * (n + 1)
            for u in neighbors[v]:
                c = color[u]
                if c != -1:
                    used[c] = True
            c = 0
            while used[c]:
                c += 1
            color[v] = c
        return color

    # Helper: DSATUR with optimized data structures and incremental updates
    def dsatur():
        color = [-1] * n
        saturation = [0] * n
        neighbor_colors = [set() for _ in range(n)]
        uncolored = set(range(n))

        if not uncolored:
            return color

        # Initial vertex: max degree
        v0 = max(uncolored, key=lambda x: deg[x])
        color[v0] = 0
        uncolored.remove(v0)
        for u in neighbors[v0]:
            if u in uncolored:
                neighbor_colors[u].add(0)
                saturation[u] = 1

        while uncolored:
            # Select vertex: max saturation, then max degree in uncolored subgraph, then min index
            v = -1
            max_sat = -1
            max_deg = -1
            for u in uncolored:
                sat = saturation[u]
                d = len(neighbors[u] & uncolored)
                if sat > max_sat or (sat == max_sat and d > max_deg) or (sat == max_sat and d == max_deg and u < v):
                    max_sat = sat
                    max_deg = d
                    v = u

            # Assign smallest available color
            used = neighbor_colors[v]
            c = 0
            while c in used:
                c += 1
            color[v] = c
            uncolored.remove(v)

            # Update saturation for uncolored neighbors
            for u in neighbors[v]:
                if u in uncolored:
                    if c not in neighbor_colors[u]:
                        neighbor_colors[u].add(c)
                        saturation[u] += 1
        return color

    # Helper: RLF (Recursive Largest First) with efficient independent set construction
    def rlf():
        color = [-1] * n
        uncolored = set(range(n))
        c = 0

        # Maintain degree in uncolored subgraph
        deg_uncolored = [len(neighbors[v] & uncolored) for v in range(n)]

        while uncolored:
            # Build maximal independent set for color c
            S = set()
            # Choose vertex with max degree in uncolored subgraph
            v = max(uncolored, key=lambda x: deg_uncolored[x])
            S.add(v)
            # Partition: U (eligible), W (ineligible)
            U = uncolored - {v} - neighbors[v]
            W = neighbors[v] & uncolored

            # Update deg_uncolored for v and its neighbors (v removed)
            for u in neighbors[v]:
                if u in uncolored:
                    deg_uncolored[u] -= 1
            deg_uncolored[v] = 0  # v is removed

            while U:
                # Select u in U with max neighbors in W, tie-break by min degree in U
                best_u = None
                max_w_neighbors = -1
                min_deg_in_U = math.inf
                for u in U:
                    w_neighbors = len(neighbors[u] & W)
                    deg_in_U = len(neighbors[u] & U)
                    if w_neighbors > max_w_neighbors or (w_neighbors == max_w_neighbors and deg_in_U < min_deg_in_U):
                        max_w_neighbors = w_neighbors
                        min_deg_in_U = deg_in_U
                        best_u = u
                S.add(best_u)
                U.remove(best_u)
                # Move neighbors of best_u from U to W
                for nb in neighbors[best_u]:
                    if nb in U:
                        U.remove(nb)
                        W.add(nb)
                # Update deg_uncolored for best_u and its neighbors
                for u in neighbors[best_u]:
                    if u in uncolored:
                        deg_uncolored[u] -= 1
                deg_uncolored[best_u] = 0  # best_u is removed

            # Assign color c to all in S
            for v in S:
                color[v] = c
            uncolored -= S
            c += 1
        return color

    # Helper: smallest-last ordering (degeneracy ordering) with bucket optimization
    def smallest_last_order():
        if n == 0:
            return []
        remaining = set(range(n))
        order = []
        degrees = [len(neighbors[v] & remaining) for v in range(n)]
        max_deg = max(degrees) if n > 0 else 0
        buckets = [[] for _ in range(max_deg + 1)]
        for v in range(n):
            buckets[degrees[v]].append(v)
        ptr = 0
        while remaining:
            while ptr <= max_deg and not buckets[ptr]:
                ptr += 1
            if ptr > max_deg:
                break
            while buckets[ptr] and buckets[ptr][-1] not in remaining:
                buckets[ptr].pop()
            if not buckets[ptr]:
                ptr += 1
                continue
            v = buckets[ptr].pop()
            order.append(v)
            remaining.remove(v)
            for u in neighbors[v]:
                if u in remaining:
                    old_deg = degrees[u]
                    degrees[u] -= 1
                    if old_deg <= max_deg:
                        if u in buckets[old_deg]:
                            buckets[old_deg].remove(u)
                    if degrees[u] <= max_deg:
                        buckets[degrees[u]].append(u)
        return order

    # Helper: Kempe chain swap for color reduction with early termination and optimized checks
    def kempe_reduce(coloring):
        if n == 0:
            return coloring
        k = max(coloring) + 1
        if k <= 1:
            return coloring

        # Try to eliminate color classes from highest down
        for target_color in range(k - 1, 0, -1):
            # Build color classes
            color_classes = [[] for _ in range(k)]
            for v in range(n):
                color_classes[coloring[v]].append(v)

            if not color_classes[target_color]:
                continue  # Already eliminated

            changed = True
            while changed and color_classes[target_color]:
                changed = False
                v = color_classes[target_color].pop()

                # Try direct move to lower color
                for c in range(target_color):
                    conflict = False
                    for u in neighbors[v]:
                        if coloring[u] == c:
                            conflict = True
                            break
                    if not conflict:
                        coloring[v] = c
                        color_classes[c].append(v)
                        changed = True
                        break
                if changed:
                    continue

                # Try Kempe chains
                for c in range(target_color):
                    # Build component of v in (c, target_color) subgraph
                    stack = [v]
                    visited = set([v])
                    component = []
                    while stack:
                        node = stack.pop()
                        component.append(node)
                        for u in neighbors[node]:
                            if coloring[u] == c or coloring[u] == target_color:
                                if u not in visited:
                                    visited.add(u)
                                    stack.append(u)

                    # Check if swapping is safe: after swap, no adjacent same color
                    safe = True
                    for x in component:
                        col_x = coloring[x]
                        for y in neighbors[x]:
                            if y not in visited:  # y not in component
                                col_y = coloring[y]
                                if col_x == c and col_y == target_color:
                                    safe = False
                                    break
                                if col_x == target_color and col_y == c:
                                    safe = False
                                    break
                        if not safe:
                            break
                    if safe:
                        # Perform swap
                        for x in component:
                            if coloring[x] == c:
                                coloring[x] = target_color
                                color_classes[target_color].append(x)
                                color_classes[c].remove(x)
                            elif coloring[x] == target_color:
                                coloring[x] = c
                                color_classes[c].append(x)
                                color_classes[target_color].remove(x)
                        changed = True
                        break  # break color loop, restart while
            # End while changed

            if not color_classes[target_color]:
                # Successfully eliminated target_color, rebuild coloring with colors 0..target_color-1 and target_color+1..k-1 shifted down
                new_coloring = [-1] * n
                for v in range(n):
                    if coloring[v] < target_color:
                        new_coloring[v] = coloring[v]
                    elif coloring[v] > target_color:
                        new_coloring[v] = coloring[v] - 1
                # Reindex colors to be contiguous
                used = [False] * target_color  # colors 0..target_color-1
                for v in range(n):
                    if new_coloring[v] != -1:
                        used[new_coloring[v]] = True
                mapping = {}
                curr = 0
                for i in range(target_color):
                    if used[i]:
                        mapping[i] = curr
                        curr += 1
                for v in range(n):
                    if new_coloring[v] != -1:
                        new_coloring[v] = mapping[new_coloring[v]]
                return new_coloring
        return coloring

    # Main: try multiple algorithms and pick best
    random.seed(42)  # Fixed seed for deterministic tie-breaking
    best_coloring = None
    best_k = math.inf

    # 1. Welsh-Powell (degree ordering)
    order_wp = sorted(range(n), key=lambda x: deg[x], reverse=True)
    cw = greedy_color(order_wp)
    kw = max(cw) + 1 if n > 0 else 0
    if kw < best_k:
        best_k = kw
        best_coloring = cw

    # 2. DSATUR
    cd = dsatur()
    kd = max(cd) + 1 if n > 0 else 0
    if kd < best_k:
        best_k = kd
        best_coloring = cd

    # 3. RLF
    cr = rlf()
    kr = max(cr) + 1 if n > 0 else 0
    if kr < best_k:
        best_k = kr
        best_coloring = cr

    # 4. Smallest-Last ordering
    order_sl = smallest_last_order()
    cs = greedy_color(order_sl)
    ks = max(cs) + 1 if n > 0 else 0
    if ks < best_k:
        best_k = ks
        best_coloring = cs

    # Apply Kempe reduction to the best found
    if best_k > 0:
        reduced = kempe_reduce(best_coloring[:])
        kr = max(reduced) + 1 if n > 0 else 0
        if kr < best_k:
            best_k = kr
            best_coloring = reduced

    # Final validation (should always hold; fallback to greedy on random order if invalid)
    valid = True
    for v in range(n):
        for u in neighbors[v]:
            if u > v:  # Check each edge once
                if best_coloring[v] == best_coloring[u]:
                    valid = False
                    break
        if not valid:
            break

    if not valid:
        # Fallback: try multiple random greedy orders
        for _ in range(10):
            order = list(range(n))
            random.shuffle(order)
            c = greedy_color(order)
            kc = max(c) + 1 if n > 0 else 0
            if kc < best_k:
                # Validate
                valid_c = True
                for v in range(n):
                    for u in neighbors[v]:
                        if u > v and c[v] == c[u]:
                            valid_c = False
                            break
                    if not valid_c:
                        break
                if valid_c:
                    best_k = kc
                    best_coloring = c
                    break
        else:
            # Last resort: greedy on original order
            best_coloring = greedy_color(list(range(n)))

    return best_coloring
